import '../catalog_database.dart';
import '../seed/open_catalog_executor.dart';
import 'bundled_catalog_data.dart';

/// Populates an already-opened [CatalogDatabase] with the bundled
/// real-data catalog (generated by `tool/build_catalog.dart` from the
/// vendored genshin-db extract — community-sourced, unverified in-game;
/// see docs/ASSUMPTIONS.md). Same mechanism as the placeholder seed the
/// tests use: only the dataset differs.
Future<void> loadBundledCatalog(CatalogDatabase db) {
  return db.batch((b) {
    b.insertAll(db.catalogMetadata, bundledCatalogMetadata);
    b.insertAll(db.gameRules, bundledGameRules);
    b.insertAll(db.characters, bundledCharacters);
    b.insertAll(db.weapons, bundledWeapons);
    b.insertAll(db.domains, bundledDomains);
    b.insertAll(db.materials, bundledMaterials);
    b.insertAll(db.domainDrops, bundledDomainDrops);
    b.insertAll(db.expCurves, bundledExpCurves);
    b.insertAll(db.ascensionRequirements, bundledAscensionRequirements);
    b.insertAll(db.talentRequirements, bundledTalentRequirements);
  });
}

/// Opens an in-memory [CatalogDatabase] loaded with the bundled catalog —
/// the app's production entry point (works identically on native and web,
/// via the same executor shim as the seed).
Future<CatalogDatabase> openBundledCatalogDatabaseInMemory() async {
  final db = CatalogDatabase(createSeedCatalogExecutor());
  final existing = await (db.selectOnly(
    db.catalogMetadata,
  )..addColumns([db.catalogMetadata.version])).get();
  if (existing.isEmpty) {
    await loadBundledCatalog(db);
  }
  return db;
}
